const staticData = $getWorkflowStaticData('global');

if (!staticData.leads) staticData.leads = {};

const root = $json;
const value = root?.entry?.[0]?.changes?.[0]?.value ?? root?.body?.entry?.[0]?.changes?.[0]?.value ?? root;
const msg = value?.messages?.[0];

if (!msg) {
  return [{ json: { ignore: true, reason: 'No WhatsApp message found' } }];
}

const phone = msg.from;
const phoneNumberId =
  value?.metadata?.phone_number_id ??
  value?.metadata?.phone_number_id ??
  'YOUR_PHONE_NUMBER_ID';

const contactName =
  value?.contacts?.[0]?.profile?.name ??
  'there';

const text = msg?.text?.body ?? '';
const buttonId = msg?.interactive?.button_reply?.id ?? '';
const listId = msg?.interactive?.list_reply?.id ?? '';
const replyId = buttonId || listId || '';

let lead = staticData.leads[phone];

if (!lead) {
  lead = {
    phone,
    name: contactName,
    step: 'welcome',
    intent: '',
    propertyType: '',
    bedrooms: '',
    budget: '',
    area: '',
    timeline: ''
  };
}

lead.name = contactName || lead.name;
lead.phone = phone;

const selection = replyId || text.trim();
const normalized = selection.toLowerCase();
const isNewLead = !staticData.leads[phone];

function setStep(next) {
  lead.step = next;
}

function buttonPayload(bodyText, buttons) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: bodyText },
      action: {
        buttons: buttons.map(b => ({
          type: 'reply',
          reply: { id: b.id, title: b.title }
        }))
      }
    }
  };
}

function listPayload(bodyText, buttonText, sections) {
  return {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: bodyText },
      action: {
        button: buttonText,
        sections
      }
    }
  };
}

const welcomeButtons = [
  { id: 'rent_property', title: 'Rent a Property' },
  { id: 'sell_property', title: 'Sell / Rent Property' },
  { id: 'see_all_options', title: 'See all options' }
];

let apiBody;
let nextStep = lead.step;
let status = 'active';

if (lead.step === 'welcome') {
  if (!selection) {
    apiBody = buttonPayload(
      `Welcome to fam Properties 👋\nHow can we help you today?`,
      welcomeButtons
    );
  } else if (normalized === 'rent_property') {
    lead.intent = 'rent';
    nextStep = 'rent_property_type';
    apiBody = buttonPayload(
      'What type of property are you looking to rent?',
      [
        { id: 'rent_apartment', title: 'Apartment' },
        { id: 'rent_villa', title: 'Villa' },
        { id: 'rent_all', title: 'See all options' }
      ]
    );
  } else if (normalized === 'sell_property') {
    lead.intent = 'sell_or_rent_out';
    nextStep = 'seller_name';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'Before we continue, what’s your name?' }
    };
  } else if (normalized === 'see_all_options') {
    nextStep = 'all_options';
    apiBody = listPayload(
      'Please choose an option:',
      'Choose',
      [{
        title: 'Services',
        rows: [
          { id: 'rent_property', title: 'Rent a Property' },
          { id: 'buy_property', title: 'Buy a Property' },
          { id: 'sell_property', title: 'Sell / Rent My Property' },
          { id: 'property_management', title: 'Property Management' }
        ]
      }]
    );
  } else if (normalized === 'buy_property') {
    lead.intent = 'buy';
    nextStep = 'buyer_name';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'Before we continue, what’s your name?' }
    };
  } else {
    apiBody = buttonPayload(
      'Welcome to fam Properties 👋\nHow can we help you today?',
      welcomeButtons
    );
  }
}

else if (lead.step === 'all_options') {
  if (normalized === 'rent_property') {
    lead.intent = 'rent';
    nextStep = 'rent_property_type';
    apiBody = buttonPayload(
      'What type of property are you looking to rent?',
      [
        { id: 'rent_apartment', title: 'Apartment' },
        { id: 'rent_villa', title: 'Villa' },
        { id: 'rent_all', title: 'See all options' }
      ]
    );
  } else if (normalized === 'buy_property') {
    lead.intent = 'buy';
    nextStep = 'buyer_name';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'Before we continue, what’s your name?' }
    };
  } else if (normalized === 'sell_property') {
    lead.intent = 'sell_or_rent_out';
    nextStep = 'seller_name';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'Before we continue, what’s your name?' }
    };
  } else {
    apiBody = listPayload('Please choose an option:', 'Choose', [{
      title: 'Services',
      rows: [
        { id: 'rent_property', title: 'Rent a Property' },
        { id: 'buy_property', title: 'Buy a Property' },
        { id: 'sell_property', title: 'Sell / Rent My Property' }
      ]
    }]);
  }
}

else if (lead.step === 'buyer_name') {
  lead.name = text.trim() || contactName;
  nextStep = 'buyer_type';
  apiBody = buttonPayload(
    'Are you buying for:',
    [
      { id: 'purpose_investment', title: 'Investment' },
      { id: 'purpose_living', title: 'Living' },
      { id: 'purpose_both', title: 'Both' }
    ]
  );
}

else if (lead.step === 'buyer_type') {
  lead.intentPurpose = selection;
  nextStep = 'buy_property_type';
  apiBody = buttonPayload(
    'What type of property?',
    [
      { id: 'buy_apartment', title: 'Apartment' },
      { id: 'buy_villa', title: 'Villa' },
      { id: 'buy_all', title: 'See all options' }
    ]
  );
}

else if (lead.step === 'buy_property_type') {
  const map = {
    buy_apartment: 'Apartment',
    buy_villa: 'Villa'
  };
  if (map[selection]) {
    lead.propertyType = map[selection];
    nextStep = 'bedrooms';
    apiBody = buttonPayload(
      'How many bedrooms?',
      [
        { id: 'bed_studio', title: 'Studio' },
        { id: 'bed_1', title: '1 Bedroom' },
        { id: 'bed_all', title: 'See all options' }
      ]
    );
  } else if (normalized === 'buy_all') {
    nextStep = 'buy_property_type_list';
    apiBody = listPayload('What type of property?', 'Choose', [{
      title: 'Property types',
      rows: [
        { id: 'buy_apartment', title: 'Apartment' },
        { id: 'buy_villa', title: 'Villa' },
        { id: 'buy_townhouse', title: 'Townhouse' },
        { id: 'buy_penthouse', title: 'Penthouse' },
        { id: 'buy_office', title: 'Office' },
        { id: 'buy_retail', title: 'Retail' },
        { id: 'buy_other', title: 'Other' }
      ]
    }]);
  } else {
    apiBody = buttonPayload('Please pick a valid option.', [
      { id: 'buy_apartment', title: 'Apartment' },
      { id: 'buy_villa', title: 'Villa' },
      { id: 'buy_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'buy_property_type_list') {
  const map = {
    buy_apartment: 'Apartment',
    buy_villa: 'Villa',
    buy_townhouse: 'Townhouse',
    buy_penthouse: 'Penthouse',
    buy_office: 'Office',
    buy_retail: 'Retail',
    buy_other: 'Other'
  };
  if (map[selection]) {
    lead.propertyType = map[selection];
    nextStep = 'bedrooms';
    apiBody = buttonPayload(
      'How many bedrooms?',
      [
        { id: 'bed_studio', title: 'Studio' },
        { id: 'bed_1', title: '1 Bedroom' },
        { id: 'bed_all', title: 'See all options' }
      ]
    );
  }
}

else if (lead.step === 'rent_property_type') {
  const map = {
    rent_apartment: 'Apartment',
    rent_villa: 'Villa'
  };
  if (map[selection]) {
    lead.propertyType = map[selection];
    nextStep = 'rent_bedrooms';
    apiBody = buttonPayload(
      'How many bedrooms?',
      [
        { id: 'rent_studio', title: 'Studio' },
        { id: 'rent_1', title: '1 Bedroom' },
        { id: 'rent_all', title: 'See all options' }
      ]
    );
  } else if (normalized === 'rent_all') {
    nextStep = 'rent_property_type_list';
    apiBody = listPayload('What type of property are you looking to rent?', 'Choose', [{
      title: 'Property types',
      rows: [
        { id: 'rent_apartment', title: 'Apartment' },
        { id: 'rent_villa', title: 'Villa' },
        { id: 'rent_townhouse', title: 'Townhouse' },
        { id: 'rent_penthouse', title: 'Penthouse' },
        { id: 'rent_office', title: 'Office' },
        { id: 'rent_retail', title: 'Retail' },
        { id: 'rent_other', title: 'Other' }
      ]
    }]);
  } else {
    apiBody = buttonPayload('Please pick a valid option.', [
      { id: 'rent_apartment', title: 'Apartment' },
      { id: 'rent_villa', title: 'Villa' },
      { id: 'rent_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'rent_property_type_list') {
  const map = {
    rent_apartment: 'Apartment',
    rent_villa: 'Villa',
    rent_townhouse: 'Townhouse',
    rent_penthouse: 'Penthouse',
    rent_office: 'Office',
    rent_retail: 'Retail',
    rent_other: 'Other'
  };
  if (map[selection]) {
    lead.propertyType = map[selection];
    nextStep = 'rent_bedrooms';
    apiBody = buttonPayload('How many bedrooms?', [
      { id: 'rent_studio', title: 'Studio' },
      { id: 'rent_1', title: '1 Bedroom' },
      { id: 'rent_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'bedrooms' || lead.step === 'rent_bedrooms') {
  const bedroomMap = {
    bed_studio: 'Studio',
    bed_1: '1 Bedroom',
    bed_2: '2 Bedrooms',
    bed_3: '3 Bedrooms',
    rent_studio: 'Studio',
    rent_1: '1 Bedroom',
    rent_2: '2 Bedrooms',
    rent_3: '3 Bedrooms'
  };
  if (bedroomMap[selection]) {
    lead.bedrooms = bedroomMap[selection];
    nextStep = 'budget';
    apiBody = buttonPayload(
      lead.intent === 'rent' ? 'What is your monthly rental budget?' : 'What is your purchase budget?',
      [
        { id: 'budget_1', title: 'Below AED 1M' },
        { id: 'budget_2', title: 'AED 1M–2M' },
        { id: 'budget_all', title: 'See all options' }
      ]
    );
  } else if (selection === 'bed_all' || selection === 'rent_all') {
    nextStep = lead.step;
    apiBody = listPayload('How many bedrooms?', 'Choose', [{
      title: 'Bedrooms',
      rows: [
        { id: lead.intent === 'rent' ? 'rent_studio' : 'bed_studio', title: 'Studio' },
        { id: lead.intent === 'rent' ? 'rent_1' : 'bed_1', title: '1 Bedroom' },
        { id: lead.intent === 'rent' ? 'rent_2' : 'bed_2', title: '2 Bedrooms' },
        { id: lead.intent === 'rent' ? 'rent_3' : 'bed_3', title: '3 Bedrooms' }
      ]
    }]);
  } else {
    apiBody = buttonPayload('Please pick a valid option.', [
      { id: lead.intent === 'rent' ? 'rent_studio' : 'bed_studio', title: 'Studio' },
      { id: lead.intent === 'rent' ? 'rent_1' : 'bed_1', title: '1 Bedroom' },
      { id: 'bed_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'budget') {
  const budgetMap = {
    budget_1: 'Below AED 1M',
    budget_2: 'AED 1M–2M',
    budget_3: 'AED 2M–5M',
    budget_4: 'Above AED 5M'
  };
  if (budgetMap[selection]) {
    lead.budget = budgetMap[selection];
    nextStep = 'area';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'Preferred area or community?\n(Or simply type the area you want)' }
    };
  } else if (selection === 'budget_all') {
    nextStep = 'budget';
    apiBody = listPayload('What is your purchase budget?', 'Choose', [{
      title: 'Budget',
      rows: [
        { id: 'budget_1', title: 'Below AED 1M' },
        { id: 'budget_2', title: 'AED 1M–2M' },
        { id: 'budget_3', title: 'AED 2M–5M' },
        { id: 'budget_4', title: 'Above AED 5M' }
      ]
    }]);
  } else {
    apiBody = buttonPayload('Please pick a valid option.', [
      { id: 'budget_1', title: 'Below AED 1M' },
      { id: 'budget_2', title: 'AED 1M–2M' },
      { id: 'budget_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'area') {
  lead.area = text.trim() || selection;
  nextStep = 'timeline';
  apiBody = buttonPayload(
    'When are you planning to purchase?',
    [
      { id: 'timeline_now', title: 'Immediately' },
      { id: 'timeline_1m', title: 'Within 1 month' },
      { id: 'timeline_all', title: 'See all options' }
    ]
  );
}

else if (lead.step === 'timeline') {
  const timelineMap = {
    timeline_now: 'Immediately',
    timeline_1m: 'Within 1 month',
    timeline_3m: 'Within 3 months',
    timeline_exploring: 'Just exploring'
  };
  if (timelineMap[selection]) {
    lead.timeline = timelineMap[selection];
    nextStep = 'complete';
    status = 'complete';

    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: {
        body:
          `Thanks, ${lead.name || 'bro'}! We've received your requirements.\n\n` +
          `A fam property consultant will contact you shortly with suitable options.`
      }
    };
  } else if (selection === 'timeline_all') {
    apiBody = listPayload('When are you planning to purchase?', 'Choose', [{
      title: 'Timeline',
      rows: [
        { id: 'timeline_now', title: 'Immediately' },
        { id: 'timeline_1m', title: 'Within 1 month' },
        { id: 'timeline_3m', title: 'Within 3 months' },
        { id: 'timeline_exploring', title: 'Just exploring' }
      ]
    }]);
  } else {
    apiBody = buttonPayload('Please pick a valid option.', [
      { id: 'timeline_now', title: 'Immediately' },
      { id: 'timeline_1m', title: 'Within 1 month' },
      { id: 'timeline_all', title: 'See all options' }
    ]);
  }
}

else if (lead.step === 'seller_name') {
  lead.name = text.trim() || contactName;
  nextStep = 'seller_type';
  apiBody = buttonPayload(
    'What would you like to do?',
    [
      { id: 'seller_sell', title: 'Sell My Property' },
      { id: 'seller_rent_out', title: 'Rent Out My Property' },
      { id: 'seller_all', title: 'See all options' }
    ]
  );
}

else if (lead.step === 'seller_type') {
  lead.sellerType = selection;
  nextStep = 'seller_property_type';
  apiBody = listPayload('What type of property do you have?', 'Choose', [{
    title: 'Property types',
    rows: [
      { id: 'seller_apartment', title: 'Apartment' },
      { id: 'seller_villa', title: 'Villa' },
      { id: 'seller_townhouse', title: 'Townhouse' },
      { id: 'seller_penthouse', title: 'Penthouse' },
      { id: 'seller_other', title: 'Other' }
    ]
  }]);
}

else if (lead.step === 'seller_property_type') {
  const map = {
    seller_apartment: 'Apartment',
    seller_villa: 'Villa',
    seller_townhouse: 'Townhouse',
    seller_penthouse: 'Penthouse',
    seller_other: 'Other'
  };
  if (map[selection]) {
    lead.propertyType = map[selection];
    nextStep = 'seller_area';
    apiBody = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'text',
      text: { body: 'What area or community is the property in?' }
    };
  }
}

else if (lead.step === 'seller_area') {
  lead.area = text.trim() || selection;
  nextStep = 'seller_done';
  status = 'complete';
  apiBody = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'text',
    text: {
      body: `Thanks, ${lead.name || 'there'}! We've received your property details. A fam consultant will contact you shortly.`
    }
  };
}

else {
  // If a completed lead messages again, show the main menu.
  nextStep = 'welcome';
  apiBody = buttonPayload(
    'Welcome back 👋\nHow can we help you today?',
    welcomeButtons
  );
}

lead.step = nextStep;
staticData.leads[phone] = lead;

return [{
  json: {
    ignore: false,
    phone,
    phone_number_id: phoneNumberId,
    lead,
    apiBody,
    raw_selection: selection,
    status
  }
}];
